<script lang="ts">import Shell from '$lib/components/Shell.svelte';import {invalidateAll} from '$app/navigation';import {Sparkles,Check,ThumbsDown,Clock3,ChevronRight} from 'lucide-svelte';let {data}=$props();const d=$derived(data.snapshot);const open=$derived(d.exceptions.filter((x:any)=>x.status==='open'||x.status==='unresolved'));let selected=$state<string|null>(null);let pending=$state(false);let error=$state('');const current=()=>open.find((x:any)=>x.id===selected)??open[0];const eventMap=$derived(new Map(d.events.map((e:any)=>[e.id,e])));const edgeMap=$derived(new Map(d.edges.map((e:any)=>[e.id,e])));const money=(e:any)=>new Intl.NumberFormat('en-US',{style:'currency',currency:e.currency}).format(e.amount/100);async function decide(action:string){const c=current();if(!c)return;pending=true;error='';try{const r=await fetch('/api/review',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({exceptionId:c.id,action})});if(!r.ok)throw new Error();selected=open.filter((x:any)=>x.id!==c.id)[0]?.id??null;await invalidateAll()}catch{error='Decision failed. Please retry.'}finally{pending=false}}</script>
<Shell><div class="review"><header class="page-head"><h1>Review</h1><span class="status-pill"><i class:amber={open.length>0}></i>{open.length} {open.length===1?'case':'cases'}</span></header>{#if !d.events.length}<p class="blank">Import on Overview first.</p>{:else if !d.run}<p class="blank">Run on Overview first.</p>{:else if !current()}<div class="done card"><span><Check size={24}/></span><h2>Queue cleared</h2><a class="btn secondary" href="/dashboard">Overview</a></div>{:else}{@const c=current()}{@const edge=edgeMap.get(c.agentRecommendation?.proposedEdgeId??c.candidateEdgeIds[0]??'')}<div class="review-layout"><aside class="case-list card"><header><b>Open cases</b><span>{open.length}</span></header>{#each open as item,i}<button class:active={item.id===c.id} onclick={()=>selected=item.id}><span>{String(i+1).padStart(2,'0')} · {item.type.replaceAll('_',' ')}</span><b>{item.summary}</b><ChevronRight size={15}/></button>{/each}</aside><article class="case card"><header><div><p class="eyebrow">Case {open.findIndex((x:any)=>x.id===c.id)+1} of {open.length}</p><h2>{c.summary}</h2></div><span class="chip warn">Needs decision</span></header><section class="agent"><div class="agent-icon"><Sparkles/></div><div><span>Recon Agent</span><p>{c.agentRecommendation?.recommendation??c.recommendation}</p><small>{edge?`${edge.relationship.replaceAll('_',' ')} · `:''}confidence {((c.agentRecommendation?.confidence??c.confidence)*100).toFixed(0)}%</small>{#if c.agentRecommendation?.evidence?.length}<b class="tools">Agent tools</b><ul>{#each c.agentRecommendation.evidence as ev}<li><b>{ev.label}</b> {ev.detail}</li>{/each}</ul>{/if}</div></section><section><div class="section-head"><h3>Related records</h3></div><div class="records">{#each c.relatedEventIds.map((id:string)=>eventMap.get(id)).filter(Boolean) as e}<article><div><span class="source-dot {e.source}"></span><b>{e.source} · {e.kind.replaceAll('_',' ')}</b></div><strong>{money(e)}</strong><small>{e.occurredAt.slice(0,10)} · {e.id}</small></article>{/each}</div></section><section class="evidence"><div><span>Match evidence</span><b>{edge?.reasons.join(' · ')??'No candidate relationship'}</b></div><div><span>Financial invariant</span><b class:good={c.validation?.balanced}>{c.validation?(c.validation.balanced?'Balanced':`Residual ${c.validation.residualMinor}`):'Awaiting payout context'}</b></div></section>{#if error}<p class="bad">{error}</p>{/if}<footer><div><button class="btn ghost" disabled={pending} onclick={()=>decide('unresolved')}><Clock3 size={14}/>Defer</button><button class="btn ghost reject" disabled={pending} onclick={()=>decide('reject')}><ThumbsDown size={14}/>Reject</button><button class="btn" disabled={pending} onclick={()=>decide('approve')}><Check size={15}/>{pending?'Saving…':'Approve match'}</button></div></footer></article></div><section class="policies"><div class="section-head"><h2>Approved policies</h2><span>{d.policies.length} active</span></div>{#if !d.policies.length}<p>None yet.</p>{:else}<div class="policy-grid">{#each d.policies as p}<article class="card"><span>{p.source} · {p.eventKind}</span><b>{p.action}</b><small>{p.conditions.map((x:any)=>x.type.replaceAll('_',' ')).join(' · ')}</small></article>{/each}</div>{/if}</section>{/if}</div></Shell>
<style>.review{display:flex;flex-direction:column;gap:16px}.blank{margin:0;color:var(--muted);font-size:13px}.status-pill i.amber{background:var(--amber)}.review-layout{display:grid;grid-template-columns:260px minmax(0,1fr);gap:18px;align-items:start}.case-list{overflow:hidden}.case-list>header{height:52px;padding:0 14px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);font-size:12px}.case-list>header span{font:10px 'DM Mono';background:#eef1ec;padding:4px 7px;border-radius:99px}.case-list button{width:100%;border:0;border-bottom:1px solid var(--line);background:#fff;text-align:left;padding:14px;display:grid;grid-template-columns:1fr auto;gap:6px;position:relative}.case-list button.active{background:#eef3e8;box-shadow:inset 3px 0 var(--green)}.case-list button span{grid-column:1/-1;font:8px 'DM Mono';text-transform:uppercase;color:var(--muted)}.case-list button b{font-size:11px;line-height:1.45;font-weight:600}.case-list button :global(svg){align-self:center}.case{padding:22px}.case>header{display:flex;justify-content:space-between;align-items:start;padding-bottom:19px;border-bottom:1px solid var(--line)}.case h2{font-size:18px;margin:8px 0 0}.case .chip.warn{color:#9a5d14;background:#fff7e8;border-color:#efd6af}.agent{display:flex;gap:14px;margin:20px 0;padding:16px;background:#f3f3ed;color:var(--ink);border:1px solid var(--line);border-radius:10px}.agent-icon{display:grid;place-items:center;flex:0 0 37px;height:37px;border-radius:8px;background:#f1e5da;color:var(--brand)}.agent-icon :global(svg){width:18px}.agent span{font:8px 'DM Mono';text-transform:uppercase;letter-spacing:.11em;color:var(--brand)}.agent p{font-size:12px;line-height:1.55;margin:7px 0}.agent ul{margin:10px 0 0;padding:0;list-style:none;display:grid;gap:6px}.agent li{font:10px 'DM Mono';color:var(--muted);line-height:1.45}.agent li b{color:var(--ink);margin-right:6px}.agent .tools{display:block;margin:10px 0 0;font:8px 'DM Mono';text-transform:uppercase;letter-spacing:.11em;color:var(--brand)}.agent small{font:9px 'DM Mono';color:var(--muted)}.records{display:grid;grid-template-columns:repeat(2,1fr);gap:9px}.records article{border:1px solid var(--line);border-radius:8px;padding:12px}.records article>div{display:flex;align-items:center}.records b{font-size:9px;text-transform:uppercase}.records strong{display:block;font:500 16px 'DM Mono';margin:12px 0 6px}.records small{font:8px 'DM Mono';color:var(--muted)}.source-dot{width:7px;height:7px;border-radius:50%;margin-right:7px;background:var(--green)}.source-dot.stripe{background:#635bff}.source-dot.gumroad{background:#dd66c8}.source-dot.dodo{background:#c99727}.source-dot.bank{background:#117aca}.evidence{display:grid;grid-template-columns:1fr 1fr;margin-top:18px;border-block:1px solid var(--line)}.evidence>div{padding:14px 0;display:grid;gap:6px}.evidence>div+div{padding-left:17px;border-left:1px solid var(--line)}.evidence span{font:8px 'DM Mono';text-transform:uppercase;color:var(--muted)}.evidence b{font-size:10px;line-height:1.5}.case footer{display:flex;align-items:center;justify-content:flex-end;padding-top:19px}.case footer>div{display:flex;gap:7px}.case footer .btn{min-height:38px;padding:0 12px;font-size:10px}.reject{color:var(--red)!important}.done{text-align:center;padding:60px}.done>span{margin:auto;display:grid;place-items:center;width:50px;height:50px;background:#e4f0e8;color:var(--green);border-radius:50%}.done a{margin-top:13px}.policies>p{font-size:12px;color:var(--muted)}.policy-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.policy-grid article{padding:14px;display:grid;gap:7px}.policy-grid span,.policy-grid small{font:8px 'DM Mono';text-transform:uppercase;color:var(--muted)}.policy-grid b{font-size:11px}@media(max-width:1050px){.review-layout{grid-template-columns:1fr}.case-list{display:flex;overflow:auto}.case-list>header{display:none}.case-list button{min-width:220px;border-right:1px solid var(--line)}}@media(max-width:650px){.records,.evidence,.policy-grid{grid-template-columns:1fr}.evidence>div+div{border-left:0;padding-left:0;border-top:1px solid var(--line)}.case footer{align-items:start;flex-direction:column;gap:12px}.case footer>div{width:100%;flex-wrap:wrap}.case{padding:15px}}</style>
